-- Extended synthetic showcase, applied after demo.sql in the same transaction.
-- Stable identities; existing values are preserved. Only known DEMO games are enriched.
ON CONFLICT  DO NOTHING;

ON CONFLICT  DO NOTHING;

ON CONFLICT  DO NOTHING;

ON CONFLICT  DO NOTHING;

ON CONFLICT  DO NOTHING;

ON CONFLICT  DO NOTHING;

ON CONFLICT  DO NOTHING;

UPDATE player_game_info i SET position = upper(m.role::text) FROM players p, team_memberships m WHERE i.player_id=p.id AND m.discord_user_id=p.discord_user_id AND m.team_id=i.team_id AND i.position IS NULL AND i.match_game_id IN (SELECT id FROM match_games WHERE external_game_id = 'DEMO-GAME-001' OR external_game_id LIKE 'DEMO-SHOWCASE-%') AND i.player_id::text LIKE '40000000-0000-4000-8000-%';

UPDATE player_game_stats s SET
  double_kills=coalesce(s.double_kills, CASE WHEN s.kills >= 4 THEN 1 ELSE 0 END),
  triple_kills=coalesce(s.triple_kills, CASE WHEN s.kills >= 7 THEN 1 ELSE 0 END),
  quadra_kills=coalesce(s.quadra_kills, 0),
  penta_kills=coalesce(s.penta_kills, 0),
  largest_killing_spree=coalesce(s.largest_killing_spree, least(s.kills, 5)),
  gold_earned=coalesce(s.gold_earned, CASE WHEN i.position='SUPPORT' THEN 9500 ELSE 12500+s.kills*300 END),
  level=coalesce(s.level, CASE WHEN i.position='SUPPORT' THEN 14 ELSE 17 END),
  damage_taken_from_champions=coalesce(s.damage_taken_from_champions, 18000+s.deaths*1800),
  damage_mitigated=coalesce(s.damage_mitigated, CASE WHEN i.position='TOP' THEN 32000 ELSE 15000 END),
  crowd_control_time=coalesce(s.crowd_control_time, 20+s.assists*2),
  turrets_killed=coalesce(s.turrets_killed, CASE WHEN i.position='ADC' THEN 3 ELSE 0 END),
  turret_takedowns=coalesce(s.turret_takedowns, 3),
  inhibitors_killed=coalesce(s.inhibitors_killed, CASE WHEN i.position='ADC' AND i.team_id=g.winner_team_id THEN 1 ELSE 0 END),
  inhibitor_takedowns=coalesce(s.inhibitor_takedowns, CASE WHEN i.team_id=g.winner_team_id THEN 1 ELSE 0 END),
  wards_placed=coalesce(s.wards_placed, CASE WHEN i.position='SUPPORT' THEN 32 ELSE 12 END),
  wards_destroyed=coalesce(s.wards_destroyed, CASE WHEN i.position='SUPPORT' THEN 9 ELSE 3 END),
  control_wards_purchased=coalesce(s.control_wards_purchased, 4),
  detector_wards_placed=coalesce(s.detector_wards_placed, 4),
  pings=coalesce(s.pings, 25+s.assists),
  summoner_spell_1_casts=coalesce(s.summoner_spell_1_casts, 5),
  summoner_spell_2_casts=coalesce(s.summoner_spell_2_casts, CASE WHEN i.position='JUNGLE' THEN 18 ELSE 6 END),
  dragons_killed=coalesce(s.dragons_killed, CASE WHEN i.position='JUNGLE' THEN CASE WHEN i.team_id=g.winner_team_id THEN 3 ELSE 1 END ELSE 0 END),
  barons_killed=coalesce(s.barons_killed, CASE WHEN i.position='JUNGLE' AND i.team_id=g.winner_team_id THEN 1 ELSE 0 END),
  rift_heralds_killed=coalesce(s.rift_heralds_killed, CASE WHEN i.position='JUNGLE' AND i.team_id=g.winner_team_id THEN 1 ELSE 0 END),
  void_grubs_killed=coalesce(s.void_grubs_killed, CASE WHEN i.position='JUNGLE' THEN 3 ELSE 0 END),
  elder_dragons_killed=coalesce(s.elder_dragons_killed, 0),
  objectives_stolen=coalesce(s.objectives_stolen, 0),
  objectives_stolen_assists=coalesce(s.objectives_stolen_assists, 0),
  largest_ability_damage=coalesce(s.largest_ability_damage, 650+s.kills*60),
  largest_attack_damage=coalesce(s.largest_attack_damage, 250+s.kills*35),
  largest_critical_strike=coalesce(s.largest_critical_strike, CASE WHEN i.position='ADC' THEN 850 ELSE 0 END),
  longest_time_living=coalesce(s.longest_time_living, g.duration_seconds/3),
  time_spent_dead=coalesce(s.time_spent_dead, s.deaths*32)
FROM player_game_info i JOIN match_games g ON g.id=i.match_game_id WHERE (s.double_kills IS NULL OR s.triple_kills IS NULL OR s.quadra_kills IS NULL OR s.penta_kills IS NULL OR s.largest_killing_spree IS NULL OR s.gold_earned IS NULL OR s.level IS NULL OR s.damage_taken_from_champions IS NULL OR s.damage_mitigated IS NULL OR s.crowd_control_time IS NULL OR s.turrets_killed IS NULL OR s.turret_takedowns IS NULL OR s.inhibitors_killed IS NULL OR s.inhibitor_takedowns IS NULL OR s.wards_placed IS NULL OR s.wards_destroyed IS NULL OR s.control_wards_purchased IS NULL OR s.detector_wards_placed IS NULL OR s.pings IS NULL OR s.summoner_spell_1_casts IS NULL OR s.summoner_spell_2_casts IS NULL OR s.dragons_killed IS NULL OR s.barons_killed IS NULL OR s.rift_heralds_killed IS NULL OR s.void_grubs_killed IS NULL OR s.elder_dragons_killed IS NULL OR s.objectives_stolen IS NULL OR s.objectives_stolen_assists IS NULL OR s.largest_ability_damage IS NULL OR s.largest_attack_damage IS NULL OR s.largest_critical_strike IS NULL OR s.longest_time_living IS NULL OR s.time_spent_dead IS NULL) AND s.id=i.id AND i.match_game_id IN (SELECT id FROM match_games WHERE external_game_id = 'DEMO-GAME-001' OR external_game_id LIKE 'DEMO-SHOWCASE-%') AND i.player_id::text LIKE '40000000-0000-4000-8000-%';

UPDATE player_game_build b SET summoner_spell_1_id=coalesce(b.summoner_spell_1_id,4), summoner_spell_2_id=coalesce(b.summoner_spell_2_id,CASE WHEN i.position='JUNGLE' THEN 11 ELSE 12 END) FROM player_game_info i WHERE (b.summoner_spell_1_id IS NULL OR b.summoner_spell_2_id IS NULL) AND b.id=i.id AND i.match_game_id IN (SELECT id FROM match_games WHERE external_game_id = 'DEMO-GAME-001' OR external_game_id LIKE 'DEMO-SHOWCASE-%') AND i.player_id::text LIKE '40000000-0000-4000-8000-%';
